/// <summary>
/// Metcash monthly duty roll processing class
/// </summary>
final class METDutyRollMonthlyProcessingJob
{
    boolean             runForExcise;
    RecordInsertList    recordInsertList;
    TransDate           startDate;    
    private TransDate   effectiveDate;
    private boolean     cpi;
    private utcdatetime effectiveDateTime;


}

Method.Source:
/// <summary>
/// Main process method
/// </summary>
/// <param name = "_contract">_contract</param>
public void process(METDutyRollMonthlyContract _contract) 
{
    #OCCRetryCount

    MetDutyRollMonthlyTmp     dutyRollMonthlyTmp;
    container                   conItems;
    int                         i;

    try
    {
        ttsbegin;
        runForExcise        = _contract.parmRunForExcise();
        startDate           = _contract.parmStartDate();
        conItems            = _contract.parmConItems();
        effectiveDate       = _contract.parmEffectiveDate();
        effectiveDateTime   = DateTimeUtil::newDateTime(_contract.parmEffectiveDate(), 0);
        cpi                 = _contract.parmCpi();

        recordInsertList    = new RecordInsertList(tableNum(METDutyRollValuesLine));

        for (i=1; i <= conlen(conItems); i++)
        {                                
            dutyRollMonthlyTmp = conpeek(conItems, i);

            this.processItem(dutyRollMonthlyTmp.SiteId, dutyRollMonthlyTmp.ItemId);
        }

        recordInsertList.insertDatabase();
        ttscommit;
    }
    catch(Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

/// <summary>
/// process one item
/// </summary>
/// <param name = "_siteId">InventSiteId</param>
/// <param name = "_itemId">ItemId</param>
private void processItem(InventSiteId  _siteId, ItemId  _itemId)
{
    METDutyRollValuesLine       dutyRollValuesLine;
    InventTable                 inventTable = InventTable::find(_itemId);
    METInventTable              metInventTable = METInventTable::find(_itemId);
    METTariffItemCode           tariffItemCode;
    Qty                         lalqty;
    METCustomExcise             metCustomExciseEnum;
    InventDim                   inventDim;

    boolean                     isValid = false;

    dutyRollValuesLine.clear();
    dutyRollValuesLine.CalcDate     = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    dutyRollValuesLine.ValidFrom    = DateTimeUtil::newDateTime(startDate, 0);
    dutyRollValuesLine.Site         = _siteId;
    dutyRollValuesLine.ItemId       = _itemId;
    dutyRollValuesLine.ItemName     = InventTable::name(_itemId);

    inventDim.clear();
    inventDim.InventSiteId          = _siteId;
    inventDim                       = InventDim::findDim(inventDim);

    dutyRollValuesLine.Unit         = InventItemSalesSetup::find(_itemId, inventDim.inventDimId).METSalesUnit;

    metCustomExciseEnum             = METTariffItemCodeBase::findRecId(metInventTable.METTariffItemCodeBaseRecid).CustomsExcise;
    dutyRollValuesLine.CustomExcise = enum2Str(metCustomExciseEnum);

    tariffItemCode                  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid,effectiveDate);

    if (metCustomExciseEnum == METCustomExcise::C)
    {
        real ItempackSalesunit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_itemId,
                                                                                                      inventDim.inventDimId,
                                                                                                      1,
                                                                                                      dutyRollValuesLine.Unit,
                                                                                                      METConstants::unitEach,
                                                                                                      NoYes::No,
                                                                                                      NoYes::No); 

        dutyRollValuesLine.AverageVFD   = this.calcAvgDutyCase(_itemId, _siteId);

        if (tariffItemCode.BeerAllowance == NoYes::Yes)
        {
            //TotalDutyPerCase                  = (pack size * Bottle size * ((AlcStrn -  Ad Valorem or Beer Subsidy)/100) * Duty-LAL)
            dutyRollValuesLine.TotalDutyPerCase = ItempackSalesunit * metInventTable.BottleSize * ((metInventTable.AlcoholContent - metInventTable.metGetAdValoremRate())/100) * tariffItemCode.DutyLAL;
           // dutyRollValuesLine.TotalDutyPerCase = metInventTable.ItemPack * metInventTable.BottleSize * ((metInventTable.AlcoholContent - metInventTable.metGetAdValoremRate())/100) * tariffItemCode.DutyLAL;
        }
        else
        {
            //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))
            dutyRollValuesLine.TotalDutyPerCase = ItempackSalesunit * metInventTable.BottleSize * (metInventTable.AlcoholContent/100) * tariffItemCode.DutyLAL + (dutyRollValuesLine.AverageVFD * (metInventTable.metGetAdValoremRate()/100));
        }

        if (dutyRollValuesLine.AverageVFD)
        {
            isValid = true;
        }
    }
    else if (metCustomExciseEnum == METCustomExcise::E)
    {
        // LAL = Alcohol Content (%) x Bottle Size (L) x Quantity (each)
        lalqty = (metInventTable.AlcoholContent / 100) * metInventTable.BottleSize * metInventTable.ItemPack;
        dutyRollValuesLine.ExcisePerCase = tariffItemCode.DutyLAL * lalqty;

        if (dutyRollValuesLine.ExcisePerCase)
        {
            isValid = true;
        }
    }

    if (isValid)
    {
        recordInsertList.add(dutyRollValuesLine);
    }
}

/// <summary>
/// calculate average VFD and average inventory quantity
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_siteId">InventSiteId</param>
/// <returns>METValueForDuty</returns>
private METValueForDuty calcAvgDutyCase(ItemId _itemId, InventSiteId _siteId)
{
    METValueForDuty avgDuty;
    METExciseInformationTable   exciseInformationTable;
    METExciseRegisterEntry      exciseRegisterEntry;
    PurchLine                   purchLine;
    TransDateTime               startDateTime;
    TransDateTime               endDateTime;
    TransDate                   transDate;
    int                         countRecords;
    InventTransferLine          inventTransferLine;
    Amount                      dutyRateReceived = 0;
    METPOTODutyRecords          metPOTODutyRecords;
    RecordInsertList            recordInsertListTmp;
    int                         poLinesCount;
    int                         toReceiptLinesCount;   

    recordInsertListtmp = new RecordInsertList(tableNum(METPOTODutyRecords), true, true, true, true, true, metPOTODutyRecords);

    utcdatetime currentDateTime =DateTimeUtil::utcNow();

    if (this.isFutureMonth(effectiveDate))
    {
        utcdatetime                 currentMonthStartDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::newDateTime(dateStartMth(DateTimeUtil::date(currentDateTime)), 0), InventSite::find(_siteId).Timezone);
        utcdatetime                 midMonthDateTime = dateStartMth(DateTimeUtil::date(currentDateTime)) + 14;
        midMonthDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::newDateTime(DateTimeUtil::date(midMonthDateTime), 86399), InventSite::find(_siteId).Timezone);

        if (midMonthDateTime > currentDateTime)
        {
            midMonthDateTime = currentDateTime;
        }

        while select firstonly10 exciseInformationTable
            index hint InventTransIdx
            order by exciseInformationTable.CreatedDateTime desc
                where exciseInformationTable.ItemId == _itemId &&
                      exciseInformationTable.SiteId == _siteId &&
                      (exciseInformationTable.InventTransType == InventTransType::Purch ||
                      exciseInformationTable.InventTransType == InventTransType::TransferOrderReceive) &&
                      exciseInformationTable.CreatedDateTime >= currentMonthStartDateTime &&
                      exciseInformationTable.CreatedDateTime <= midMonthDateTime
        {
            if (countRecords == METConstants::TenValue)
            {
                /// createddateteime + dutyvalue
                break;
            }

            select firstonly validtimestate(currentDateTime) DutyRateReceived from exciseRegisterEntry
                where exciseRegisterEntry.ReferenceId == exciseInformationTable.ExciseRegisterReferenceId;

            metPOTODutyRecords.clear();
            metPOTODutyRecords.CreatedDateTimeVal = exciseRegisterEntry.CreatedDateTime;
            metPOTODutyRecords.DutyRateReceived = exciseRegisterEntry.DutyRateReceived;
            recordInsertListtmp.add(metPOTODutyRecords);

            dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
            countRecords++;
        }

        recordInsertListtmp.insertDatabase();

        METDutyRateReceived metDutyRateReceivedSumFuture;
        while select firstonly10 DutyRateReceived from metPOTODutyRecords
            order by CreatedDateTimeVal desc
        {
            metDutyRateReceivedSumFuture += metPOTODutyRecords.DutyRateReceived; 
        }

        if (countRecords)
        {
            avgDuty = metDutyRateReceivedSumFuture / countRecords;
        }
    }
    else
    {
        while select firstonly10 exciseInformationTable
            index hint InventTransIdx
            order by exciseInformationTable.ModifiedDateTime desc
                where exciseInformationTable.ItemId == _itemId &&
                      exciseInformationTable.SiteId == _siteId &&
                      (exciseInformationTable.InventTransType == InventTransType::Purch ||
                      exciseInformationTable.InventTransType == InventTransType::TransferOrderReceive)
        {
            if (countRecords == METConstants::TenValue)
            {
                /// createddateteime + dutyvalue
                break;
            }

            select firstonly validtimestate(currentDateTime) DutyRateReceived from exciseRegisterEntry
                where exciseRegisterEntry.ReferenceId == exciseInformationTable.ExciseRegisterReferenceId;

            metPOTODutyRecords.clear();
            metPOTODutyRecords.CreatedDateTimeVal = exciseInformationTable.CreatedDateTime;
            metPOTODutyRecords.DutyRateReceived = exciseRegisterEntry.DutyRateReceived;
            recordInsertListtmp.add(metPOTODutyRecords);
            dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
            countRecords++;
        }

        recordInsertListtmp.insertDatabase();

        METDutyRateReceived metDutyRateReceivedSum;

        while select firstonly10 DutyRateReceived from metPOTODutyRecords
            order by CreatedDateTimeVal desc
        {
            metDutyRateReceivedSum += metPOTODutyRecords.DutyRateReceived;
        }

        if (countRecords)
        {
            avgDuty = metDutyRateReceivedSum / countRecords;
        }
    }
    return avgDuty;
}

/// <summary>
/// get current or future month
/// </summary>
/// <param name = "_inputDate">_inputDate</param>
/// <returns>boolean</returns>
public boolean isFutureMonth(Transdate _inputDate)
{
    date currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    // Check if the date is in current month
    if (mthOfYr(_inputDate) == mthOfYr(currentDate) && year(_inputDate) == year(currentDate))
    {
        return false; // Current month
    }

    // Check if the date is in future month
    if ((year(_inputDate) > year(currentDate)) ||
    (year(_inputDate) == year(currentDate) && mthOfYr(_inputDate) > mthOfYr(currentDate)))
    {
        return true; // Future month
    }

    return false; // Past month
}

/// <summary>
///  This is to get the Friday date of the week for a given date
/// </summary>
/// <param name = "_inputDate">15th of any month</param>
/// <returns>transDateTime</returns>
public TransDateTime getFridayDateTime(TransDate _inputDate)
{
    TransDateTime fridayDateTime;
    int dayOfWk = dayOfWk(_inputDate);

    int daysOffset = dayOfWk >= 5 ? 7 - dayOfWk : 7 - (5 - dayOfWk);

    fridayDateTime = DateTimeUtil::newDateTime(_inputDate - daysOffset, 86399);
    return fridayDateTime;
}
